<?php
function gh_distance_m($a,$b){$r=6371000;$p1=deg2rad((float)$a['latitude']);$p2=deg2rad((float)$b['latitude']);$dp=deg2rad((float)$b['latitude']-(float)$a['latitude']);$dl=deg2rad((float)$b['longitude']-(float)$a['longitude']);$x=sin($dp/2)*sin($dp/2)+cos($p1)*cos($p2)*sin($dl/2)*sin($dl/2);return $r*2*atan2(sqrt($x),sqrt(1-$x));}
function gh_clean_trace($rows){$clean=array();foreach($rows as $r){$accuracy=(float)$r['accuracy_m'];$provider=strtolower((string)$r['provider']);if($accuracy>60)continue;if($provider==='network'&&$accuracy>45)continue;$clean[]=$r;}$result=array();$n=count($clean);for($i=0;$i<$n;$i++){if($i>0&&$i<$n-1){$a=$clean[$i-1];$b=$clean[$i];$c=$clean[$i+1];$ab=gh_distance_m($a,$b);$bc=gh_distance_m($b,$c);$ac=gh_distance_m($a,$c);if($ab>90&&$bc>90&&$ac<70)continue;}$result[]=$clean[$i];}return $result;}
function gh_osrm_get($url){if(function_exists('curl_init')){$ch=curl_init($url);curl_setopt_array($ch,array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>25,CURLOPT_USERAGENT=>'GraffitiHunter/0.5.6 (+https://graffitihunter.net)'));$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($code===200&&$body)return $body;return false;}$ctx=stream_context_create(array('http'=>array('timeout'=>25,'header'=>"User-Agent: GraffitiHunter/0.5.6 (+https://graffitihunter.net)\r\n")));return @file_get_contents($url,false,$ctx);}
function gh_match_segment($segment){$all=array();for($offset=0;$offset<count($segment)-1;$offset+=9){$chunk=array_slice($segment,$offset,10);if(count($chunk)<2)break;$coords=$times=array();foreach($chunk as $p){$coords[]=sprintf('%.7f,%.7f',$p['longitude'],$p['latitude']);$times[]=strtotime($p['recorded_at']);}$url='https://router.project-osrm.org/match/v1/driving/'.implode(';',$coords).'?geometries=geojson&overview=full&tidy=true&gaps=split&timestamps='.implode(';',$times);$body=gh_osrm_get($url);if(!$body)continue;$json=json_decode($body,true);if(empty($json['matchings']))continue;foreach($json['matchings'] as $match){if(isset($match['geometry']['coordinates'])&&count($match['geometry']['coordinates'])>1)$all[]=$match['geometry']['coordinates'];}}return $all;}
function gh_map_match_track($pdo,$trackId){$q=$pdo->prepare('SELECT sequence_no,recorded_at,latitude,longitude,accuracy_m,provider FROM gh_walk_points WHERE track_id=? ORDER BY sequence_no');$q->execute(array($trackId));$raw=$q->fetchAll();$clean=gh_clean_trace($raw);$segments=array();$current=array();$last=null;foreach($clean as $p){$t=strtotime($p['recorded_at']);if($last!==null&&$t-$last>90){if(count($current)>1)$segments[]=$current;$current=array();}$current[]=$p;$last=$t;}if(count($current)>1)$segments[]=$current;$lines=array();foreach($segments as $segment)$lines=array_merge($lines,gh_match_segment($segment));$geometry=null;if(count($lines)===1)$geometry=array('type'=>'LineString','coordinates'=>$lines[0]);elseif(count($lines)>1)$geometry=array('type'=>'MultiLineString','coordinates'=>$lines);$status=$geometry?'matched':'no_match';$pdo->prepare('UPDATE gh_walk_tracks SET matched_geojson=?,match_status=?,filtered_point_count=? WHERE id=?')->execute(array($geometry?json_encode($geometry):null,$status,count($clean),$trackId));return array('status'=>$status,'input_points'=>count($raw),'clean_points'=>count($clean),'matched_lines'=>count($lines));}
